package com.wizzadrds.theworldremembers.voice; import java.io.*; import java.nio.file.*; import java.nio.charset.StandardCharsets; public final class ProcessSpeechToTextAdapter implements SpeechToTextAdapter { private final Path executable; public ProcessSpeechToTextAdapter(Path executable){this.executable=executable;} public String transcribe(Path audio)throws IOException,InterruptedException{if(!Files.isRegularFile(audio))throw new FileNotFoundException(audio.toString());Process p=new ProcessBuilder(executable.toString(),audio.toAbsolutePath().toString()).redirectErrorStream(true).start();String out=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8).trim();int code=p.waitFor();if(code!=0)throw new IOException("Local STT exited with "+code);return out;} }
